        btn.on(Laya.Event.MOUSE_DOWN, null, function(e) {
          if (e && e.stopPropagation) e.stopPropagation();
          var isDragging = false;
          var startX = e.stageX;
          var startY = e.stageY;
          var initX = btn.x;
          var initY = btn.y;

          var onMove = function(e2) {
            var dx = e2.stageX - startX;
            var dy = e2.stageY - startY;
            if (Math.abs(dx) > 6 || Math.abs(dy) > 6) {
              isDragging = true;
              btn.pos(
                Math.max(0, Math.min((Laya.stage.width || 720) - 230, initX + dx)),
                Math.max(40, Math.min((Laya.stage.height || 1334) - 80, initY + dy))
              );
            }
          };

          var onUp = function(e3) {
            Laya.stage.off(Laya.Event.MOUSE_MOVE, null, onMove);
            Laya.stage.off(Laya.Event.MOUSE_UP, null, onUp);
            if (!isDragging) {
              self.toggleMenu();
            }
          };

          Laya.stage.on(Laya.Event.MOUSE_MOVE, null, onMove);
          Laya.stage.on(Laya.Event.MOUSE_UP, null, onUp);
        });

        Laya.stage.addChild(btn);
